cd /output && node -e "
import('./lib/aes.mjs').then(({ aesEcbEncryptBlock }) => {
  const hex = (u8) => Buffer.from(u8).toString('hex');
  const fromHex = (h) => Uint8Array.from(Buffer.from(h, 'hex'));

  // FIPS-197 AES-128 known answer
  const k1 = fromHex('000102030405060708090a0b0c0d0e0f');
  const p1 = fromHex('00112233445566778899aabbccddeeff');
  const c1 = hex(aesEcbEncryptBlock(k1, p1));
  console.log('AES-128 vector:', c1, c1 === '69c4e0d86a7b0430d8cdb78070b4c55a' ? 'PASS' : 'FAIL');

  // pyaes-produced vector
  const k2 = new TextEncoder().encode('4)9PfvFH4vtYbj #');
  const p2 = new TextEncoder().encode('Fgoy\$38USLH;|sEff');
  const c2 = hex(aesEcbEncryptBlock(k2, p2));
  console.log('pyaes vector:  ', c2, c2 === 'bc08feba67951857d8aba1f8b5d8a698' ? 'PASS' : 'FAIL');

  // AES-192 / AES-256 FIPS-197 vectors
  const k192 = fromHex('000102030405060708090a0b0c0d0e0f1011121314151617');
  const c192 = hex(aesEcbEncryptBlock(k192, p1));
  console.log('AES-192 vector:', c192, c192 === 'dda97ca4864cdfe06eaf70a0ec0d7191' ? 'PASS' : 'FAIL');
  const k256 = fromHex('000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f');
  const c256 = hex(aesEcbEncryptBlock(k256, p1));
  console.log('AES-256 vector:', c256, c256 === '8ea2b7ca516745bfeafc49904b496089' ? 'PASS' : 'FAIL');

  // Invalid key sizes throw Error('Invalid key size')
  for (const bad of [0, 8, 15, 17, 20, 33]) {
    try { aesEcbEncryptBlock(new Uint8Array(bad), p1); console.log('keylen', bad, 'FAIL: no throw'); }
    catch (e) { console.log('keylen', bad, e instanceof Error && e.message === 'Invalid key size' ? 'PASS' : 'FAIL: ' + e.message); }
  }

  // Return type check
  const out = aesEcbEncryptBlock(k1, p1);
  console.log('returns Uint8Array len 16:', out instanceof Uint8Array && out.length === 16 ? 'PASS' : 'FAIL');
});
"

