cd /output && node -e '
// Generate the AES S-box algorithmically and diff against the table in aes.mjs
const src = require("fs").readFileSync("./lib/aes.mjs", "utf8");
const m = src.match(/const SBOX = new Uint8Array\(\[([\s\S]*?)\]\)/);
const table = eval("[" + m[1] + "]");

function xtime(a){ return ((a<<1) ^ ((a&0x80)?0x1b:0)) & 0xff; }
function gmul(a,b){ let p=0; for(let i=0;i<8;i++){ if(b&1)p^=a; const hi=a&0x80; a=(a<<1)&0xff; if(hi)a^=0x1b; b>>=1;} return p; }
function inv(a){ if(a===0) return 0; let r=1, x=a, e=254; while(e){ if(e&1) r=gmul(r,x); x=gmul(x,x); e>>=1;} return r; }
function sboxGen(a){
  const b = inv(a); let s = b;
  for (let i=1;i<=4;i++){ // rotate b left by i bits within a byte, XOR
    const rot = ((b<<i)|(b>>(8-i))) & 0xff;
    s ^= rot;
  }
  return (s ^ 0x63) & 0xff;
}
let bad = [];
for (let i=0;i<256;i++){ if (table[i] !== sboxGen(i)) bad.push([i, table[i], sboxGen(i)]); }
console.log("table len:", table.length, "mismatches:", JSON.stringify(bad));
'
